import 'package:flutter/material.dart';
import 'package:stacked/stacked.dart';
import '../../../services/ai_agent_service.dart';
class AiAgentView extends StatefulWidget{const AiAgentView({super.key,required this.permissions});final Set<String> permissions;@override State<AiAgentView> createState()=>_AiAgentViewState();}
class _AiAgentViewState extends State<AiAgentView>{late final AiAgentViewModel vm;@override void initState(){super.initState();vm=AiAgentViewModel(AiAgentService(),widget.permissions)..load();}@override void dispose(){vm.dispose();super.dispose();}
 @override Widget build(BuildContext context)=>AnimatedBuilder(animation:vm,builder:(context,_)=>DefaultTabController(length:2,child:Scaffold(appBar:AppBar(title:const Text('AI Agent'),bottom:const TabBar(tabs:[Tab(text:'Conversations'),Tab(text:'Approvals')])),floatingActionButton:widget.permissions.contains('ai.view')?FloatingActionButton.extended(onPressed:()=>_newConversation(context),icon:const Icon(Icons.add_comment),label:const Text('New conversation')):null,body:vm.isBusy&&!vm.loaded?const Center(child:CircularProgressIndicator()):TabBarView(children:[_ConversationList(vm),_ApprovalList(vm)]))));
 Future<void> _newConversation(BuildContext context)async{final name=TextEditingController(),phone=TextEditingController();await showDialog<void>(context:context,builder:(ctx)=>AlertDialog(title:const Text('New AI conversation'),content:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:name,decoration:const InputDecoration(labelText:'Customer name')),TextField(controller:phone,decoration:const InputDecoration(labelText:'Phone'))]),actions:[TextButton(onPressed:()=>Navigator.pop(ctx),child:const Text('Cancel')),FilledButton(onPressed:(){Navigator.pop(ctx);vm.create(name.text.trim(),phone.text.trim());},child:const Text('Create'))]));name.dispose();phone.dispose();}
}
class AiAgentViewModel extends BaseViewModel{AiAgentViewModel(this.api,this.permissions);final AiAgentService api;final Set<String> permissions;bool loaded=false;List<Map<String,dynamic>> chats=[],requests=[];String? error;bool get busy=>isBusy;
 Future<void> load()async{setBusy(true);error=null;try{final tasks=<Future<dynamic>>[api.conversations()];if(permissions.contains('ai.orders.approve'))tasks.add(api.approvals());final r=await Future.wait(tasks);chats=List<Map<String,dynamic>>.from(r[0] as List);requests=r.length>1?List<Map<String,dynamic>>.from(r[1] as List):[];loaded=true;}catch(e){error=e.toString();}finally{setBusy(false);notifyListeners();}}
 Future<void> create(String name,String phone)async{try{await api.createConversation(name:name.isEmpty?null:name,phone:phone.isEmpty?null:phone);await load();}catch(e){error=e.toString();notifyListeners();}}
 Future<void> review(String id,String decision)async{try{await api.review(id,decision);await load();}catch(e){error=e.toString();notifyListeners();}}
}
class _ConversationList extends StatelessWidget{const _ConversationList(this.vm);final AiAgentViewModel vm;@override Widget build(BuildContext context)=>RefreshIndicator(onRefresh:vm.load,child:ListView(padding:const EdgeInsets.all(12),children:[if(vm.error!=null)Text(vm.error!),if(vm.chats.isEmpty)const Padding(padding:EdgeInsets.all(20),child:Text('No AI conversations yet.')), ...vm.chats.map((c)=>Card(child:ListTile(leading:const CircleAvatar(child:Icon(Icons.smart_toy_outlined)),title:Text(c['customerName'] as String? ?? c['customerPhone'] as String? ?? 'Unknown customer'),subtitle:Text('${c['channel']} • ${c['status']}'),trailing:Text('#${c['id']}'))))]));}
class _ApprovalList extends StatelessWidget{const _ApprovalList(this.vm);final AiAgentViewModel vm;@override Widget build(BuildContext context)=>RefreshIndicator(onRefresh:vm.load,child:ListView(padding:const EdgeInsets.all(12),children:[if(!vm.permissions.contains('ai.orders.approve'))const Text('You do not have permission to review AI orders.'),if(vm.permissions.contains('ai.orders.approve')&&vm.requests.isEmpty)const Text('No pending AI approvals.'),...vm.requests.map((r){final id='${r['id']}';final reasons=(r['riskReasons'] as List? ?? []).join(' • ');final payload=r['payload'] as Map? ?? const {};final items=payload['items'] as List? ?? [];return Card(child:Padding(padding:const EdgeInsets.all(12),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Approval #$id',style:Theme.of(context).textTheme.titleMedium),Text('${payload['orderType']} • Branch ${payload['branchId']}'),Text('Items: ${items.length}'),if(reasons.isNotEmpty)Text('Risk: $reasons',style:TextStyle(color:Theme.of(context).colorScheme.error)),Row(mainAxisAlignment:MainAxisAlignment.end,children:[TextButton(onPressed:vm.busy?null:()=>vm.review(id,'rejected'),child:const Text('Reject')),const SizedBox(width:8),FilledButton(onPressed:vm.busy?null:()=>vm.review(id,'approved'),child:const Text('Approve & create order'))])])));})]));}